
import express from "express";
import path from "path";
import fs from "fs/promises";
import { randomUUID } from "crypto";
import multer from "multer";

import {
    getDocs,
    getDoc,
    addDoc,
    updateDoc,
    deleteDoc,
    doc,
    serverTimestamp
} from "firebase/firestore";

import { Dish, db } from "../../config.js";

const routes = express.Router();

// ==========================================
// Configure image storage
// ==========================================

const imageDir = path.resolve("images");

// Only delete files generated by this application
const imageNamePattern =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.(jpg|png|webp)$/i;

const storage = multer.diskStorage({
    destination: (req, file, cb) => {
        cb(null, imageDir);
    },

    filename: (req, file, cb) => {
        const ext = path.extname(file.originalname)
            .toLowerCase();

        const filename = randomUUID() + ext;

        cb(null, filename);
    }
});

// Allowed image extensions and MIME types
const allowedTypes = {
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".png": "image/png",
    ".webp": "image/webp"
};

const upload = multer({
    storage,

    limits: {
        fileSize: 5 * 1024 * 1024
    },

    fileFilter: (req, file, cb) => {
        const ext = path.extname(file.originalname)
            .toLowerCase();

        if (allowedTypes[ext] === file.mimetype) {
            cb(null, true);
        } else {
            cb(new Error(
                "Only JPEG, PNG and WebP images are allowed"
            ));
        }
    }
});

// Handle Multer errors
const uploadImage = (req, res, next) => {
    upload.single("file")(req, res, (error) => {
        if (error) {
            return res.status(400).json({
                success: false,
                msg: error.message
            });
        }

        next();
    });
};

// Remove a local uploaded file
async function removeImage(filename) {
    if (!filename || !imageNamePattern.test(filename)) {
        return;
    }

    const filePath = path.join(imageDir, filename);

    try {
        await fs.unlink(filePath);
    } catch (error) {
        if (error.code !== "ENOENT") {
            console.error("Image cleanup error:", error);
        }
    }
}

// Validate and construct dish data
function validateDish(body, isCreate = false) {
    const { name, price, categoryId, description } = body ?? {};

    const data = {};

    if (name !== undefined) {
        if (typeof name !== "string" || !name.trim()) {
            throw new Error("Invalid dish name");
        }

        data.name = name.trim();
    } else if (isCreate) {
        throw new Error("Dish name is required");
    }

    if (price !== undefined) {
        if (typeof price !== "string" &&
            typeof price !== "number") {
            throw new Error("Invalid price");
        }

        const numericPrice = Number(price);

        if (String(price).trim() === "" ||
            !Number.isFinite(numericPrice) ||
            numericPrice < 0) {
            throw new Error("Invalid price");
        }

        data.price = numericPrice;
    } else if (isCreate) {
        throw new Error("Dish price is required");
    }

    if (categoryId !== undefined) {
        if (typeof categoryId !== "string" || !categoryId.trim()) {
            throw new Error("Invalid category ID");
        }

        data.categoryId = categoryId.trim();
    } else if (isCreate) {
        throw new Error("Category ID is required");
    }

    if (description !== undefined) {
        if (typeof description !== "string") {
            throw new Error("Invalid description");
        }

        data.description = description;
    } else if (isCreate) {
        data.description = "";
    }

    return data;
}

// ==========================================
// GET - Retrieve all dishes
// ==========================================

routes.get("/", async (req, res) => {
    try {
        const result = await getDocs(Dish);

        const list = result.docs.map(doc => ({
            ...doc.data(),
            id: doc.id
        }));

        res.status(200).json({
            success: true,
            total: list.length,
            data: list
        });

    } catch (error) {
        console.error("Get dishes error:", error);

        res.status(500).json({
            success: false,
            msg: "Failed to retrieve dishes"
        });
    }
});

// ==========================================
// POST - Create a new dish
// ==========================================

routes.post("/create", uploadImage, async (req, res) => {
    try {
        const data = validateDish(req.body, true);

        const payload = {
            ...data,
            file: req.file?.filename ?? "",
            createdAt: serverTimestamp(),
            updatedAt: serverTimestamp()
        };

        const result = await addDoc(Dish, payload);

        res.status(201).json({
            success: true,
            id: result.id,
            msg: "Dish added successfully"
        });

    } catch (error) {
        // Remove uploaded image if creation fails
        if (req.file) {
            await removeImage(req.file.filename);
        }

        if (error.message.startsWith("Invalid") ||
            error.message.includes("required")) {
            return res.status(400).json({
                success: false,
                msg: error.message
            });
        }

        console.error("Create dish error:", error);

        res.status(500).json({
            success: false,
            msg: "Failed to create dish"
        });
    }
});

// ==========================================
// PUT - Update an existing dish
// ==========================================

routes.put("/update/:dish_id", uploadImage, async (req, res) => {
    try {
        const id = req.params.dish_id;

        const data = validateDish(req.body);

        if (Object.keys(data).length === 0 && !req.file) {
            return res.status(400).json({
                success: false,
                msg: "No valid fields to update"
            });
        }

        const dishRef = doc(db, "dishes", id);
        const dishSnap = await getDoc(dishRef);

        if (!dishSnap.exists()) {
            if (req.file) {
                await removeImage(req.file.filename);
            }

            return res.status(404).json({
                success: false,
                msg: "Dish not found"
            });
        }

        const oldImage = dishSnap.data().file;

        const payload = {
            ...data,
            updatedAt: serverTimestamp()
        };

        if (req.file) {
            payload.file = req.file.filename;
        }

        await updateDoc(dishRef, payload);

        // Remove old image only after successful update
        if (req.file && oldImage) {
            await removeImage(oldImage);
        }

        res.status(200).json({
            success: true,
            msg: "Dish updated successfully"
        });

    } catch (error) {
        if (req.file) {
            await removeImage(req.file.filename);
        }

        if (error.message.startsWith("Invalid")) {
            return res.status(400).json({
                success: false,
                msg: error.message
            });
        }

        console.error("Update dish error:", error);

        res.status(500).json({
            success: false,
            msg: "Failed to update dish"
        });
    }
});

// ==========================================
// DELETE - Delete a dish
// ==========================================

routes.delete("/delete/:dish_id", async (req, res) => {
    try {
        const id = req.params.dish_id;

        const dishRef = doc(db, "dishes", id);
        const dishSnap = await getDoc(dishRef);

        if (!dishSnap.exists()) {
            return res.status(404).json({
                success: false,
                msg: "Dish not found"
            });
        }

        const imageFilename = dishSnap.data().file;

        await deleteDoc(dishRef);

        // Delete associated local image
        if (imageFilename) {
            await removeImage(imageFilename);
        }

        res.status(200).json({
            success: true,
            msg: "Dish deleted successfully"
        });

    } catch (error) {
        console.error("Delete dish error:", error);

        res.status(500).json({
            success: false,
            msg: "Failed to delete dish"
        });
    }
});

export default routes;

